(98860, 4031, 554, '<td valign="top">should have placed much higher</td>', 'should have placed much higher', '2002-08-12 23:48:00.000000', NULL, 0),
(98861, 4032, 1792, '<td valign="top">Good composition, but seems to lack detail.</td>', 'Good composition, but seems to lack detail.', '2002-08-05 03:12:00.000000', NULL, 1),
(98862, 4032, 2780, '<td valign="top">nice photo, but I think there needs to be more contrast so that the house doesnt blend in so much with the background. It is also slightly out of focus.</td>', 'nice photo, but I think there needs to be more contrast so that the house doesnt blend in so much with the background. It is also slightly out of focus.', '2002-08-05 04:31:00.000000', NULL, 1),
(98863, 4032, 772, '<td valign="top">Interesting concept of ''old'' :)  This particular image may need a little more contrast to really punch harder... I also believe an angle other than straight on would add some depth to the image... - jmsetzler</td>', 'Interesting concept of ''old'' :)  This particular image may need a little more contrast to really punch harder... I also believe an angle other than straight on would add some depth to the image... - jmsetzler', '2002-08-05 10:53:00.000000', NULL, 1),
