(101200, 4187, 2798, '<td valign="top">Wow - a real cognac drinker. Lovely placement of subject and great framing. The spotlight behind the glass is just a touch too strong for my taste but it leads the eye perfectly. Excellent set up and execution. 9 from me.</td>', 'Wow - a real cognac drinker. Lovely placement of subject and great framing. The spotlight behind the glass is just a touch too strong for my taste but it leads the eye perfectly. Excellent set up and execution. 9 from me.', '2002-08-07 05:53:00.000000', NULL, 1),
(101201, 4187, 133, '<td valign="top">A very nice photograph, though I''m not sure what it is.</td>', 'A very nice photograph, though I''m not sure what it is.', '2002-08-07 09:03:00.000000', NULL, 1),
(101202, 4187, 2111, '<td valign="top">excellent 6</td>', 'excellent 6', '2002-08-07 11:07:00.000000', NULL, 1),
(101203, 4187, 885, '<td valign="top">Really interesting unique image.  I love the shadow.  I have no idea what the heck it is, but it sure makes me want to look at it :-)</td>', 'Really interesting unique image.  I love the shadow.  I have no idea what the heck it is, but it sure makes me want to look at it :-)', '2002-08-07 11:09:00.000000', NULL, 1),
