(98204, 3969, 509, '<td valign="top">Very nice colors here.  I like the close crop as well, nice job</td>', 'Very nice colors here.  I like the close crop as well, nice job', '2002-08-10 01:46:00.000000', NULL, 1),
(98205, 3969, 2361, '<td valign="top">I would really like to understand the lighting technique you have used here to bring out the highlights.  Wonderdul shot!  Jak</td>', 'I would really like to understand the lighting technique you have used here to bring out the highlights.  Wonderdul shot!  Jak', '2002-08-10 11:29:00.000000', NULL, 1),
